const FRAGMENT = Buffer.from(FRAGMENT_B64, 'base64').toString('utf8');

function stop(message) { console.error(`\nERROR: ${message}\n`); process.exit(1); }
function read(file) { return fs.readFileSync(file, 'utf8'); }
function count(source, value) { return source.split(value).length - 1; }
function replaceOnce(source, before, after, label) {
  const n = count(source, before);
  if (n !== 1) throw new Error(`${label} marker should occur once; found ${n}. No files have been changed.`);
  return source.replace(before, after);
}
function atomicWrite(file, contents) {
  const tmp = `${file}.tmp-${process.pid}`;
  fs.writeFileSync(tmp, contents, 'utf8');
  fs.renameSync(tmp, file);
}

if (!fs.existsSync(PACKAGE) || !fs.existsSync(APP) || !fs.existsSync(LOCK)) {
  stop('Open the terminal in the project root (the folder containing package.json), and confirm src/app.jsx and package-lock.json exist.');
}
let source = read(APP);
let pkg, lock;
try { pkg = JSON.parse(read(PACKAGE)); lock = JSON.parse(read(LOCK)); } catch (error) { stop(`package.json/package-lock.json could not be parsed: ${error.message}`); }

const expectedFullyPatched = source.includes('function ExcelWorkbookViewer(') &&
  source.includes('function IsoPlanningDashboardPage({ workbooks, back, openExcel })') &&
  source.includes('onClick={openExcel}>EXCEL</button>') &&
  source.includes("import { strFromU8, strToU8, unzipSync, zipSync } from 'fflate';");
if (expectedFullyPatched) {
  if (pkg.dependencies?.fflate === '0.3.11' && lock.packages?.['']?.dependencies?.fflate === '0.3.11') {
    console.log('No changes needed: Excel viewer patch is already applied.');
    process.exit(0);
  }
}
if (source.includes('function ExcelWorkbookViewer(') || source.includes("onClick={openExcel}>EXCEL</button>")) {
  stop('This app contains a partial/different Excel patch. To prevent duplicate code, restore the original app.jsx backup first, then run this safe updater. It will not replace the entire file.');
}

try {
  source = replaceOnce(source, "import * as XLSX from 'xlsx-js-style';", "import * as XLSX from 'xlsx-js-style';\nimport { strFromU8, strToU8, unzipSync, zipSync } from 'fflate';", 'XLSX import');
  source = replaceOnce(source, "  const [page, setPage] = useState('home');", "  const [page, setPage] = useState('home');\n  const [excelViewerOpen, setExcelViewerOpen] = useState(false);", 'App state');
  source = replaceOnce(source,
    "  if (page === 'iso-planning-dashboard') return <IsoPlanningDashboardPage workbooks={excelSession.workbooks} back={() => go('home')} />;",
    "  if (page === 'iso-planning-dashboard') return <><IsoPlanningDashboardPage workbooks={excelSession.workbooks} back={() => go('home')} openExcel={() => setExcelViewerOpen(true)} />{excelViewerOpen ? <ExcelWorkbookViewer existingWorkbooks={excelSession.workbooks} onClose={() => setExcelViewerOpen(false)} /> : null}</>;",
    'ISO planning route');
  source = replaceOnce(source, 'function IsoPlanningDashboardPage({ workbooks, back }) {', 'function IsoPlanningDashboardPage({ workbooks, back, openExcel }) {', 'ISO dashboard signature');
  source = replaceOnce(source,
    '        <button className="iso-top-action" onClick={openRevision}>REVISION</button>',
    '        <button className="iso-top-action" onClick={openRevision}>REVISION</button>\n        <button className="iso-top-action" onClick={openExcel}>EXCEL</button>',
    'EXCEL button position');
  source = replaceOnce(source, 'function Layout({ title, sub, back, children }) {', `${FRAGMENT}\n\nfunction Layout({ title, sub, back, children }) {`, 'viewer insertion point');
} catch (error) { stop(error.message); }

// Validate everything in memory before writing any file.
for (const required of ["import { strFromU8, strToU8, unzipSync, zipSync } from 'fflate';", 'function ExcelWorkbookViewer(', 'function ExcelDashboardReplica(', 'onClick={openExcel}>EXCEL</button>']) {
  if (!source.includes(required)) stop(`Patch validation failed for: ${required}`);
}
if (source.includes('function ExcelWorkbookViewer(', 0) && count(source, 'function ExcelWorkbookViewer(') !== 1) stop('Duplicate viewer function detected; no files were changed.');

pkg.dependencies = pkg.dependencies || {};
if (pkg.dependencies.fflate && pkg.dependencies.fflate !== '0.3.11') stop(`Unexpected fflate version in package.json: ${pkg.dependencies.fflate}. No files have been changed.`);
pkg.dependencies.fflate = '0.3.11';
if (!lock.packages || !lock.packages[''] || !lock.packages['node_modules/fflate']) stop('package-lock.json does not contain the fflate@0.3.11 package record. Run npm install fflate@0.3.11 first; no files have been changed.');
lock.packages[''].dependencies = lock.packages[''].dependencies || {};
lock.packages[''].dependencies.fflate = '0.3.11';
if (lock.packages['node_modules/fflate'].version !== '0.3.11') stop(`Lock file has unexpected fflate version ${lock.packages['node_modules/fflate'].version}.`);

const updates = [
  [APP, source],
  [PACKAGE, JSON.stringify(pkg, null, 2) + '\n'],
  [LOCK, JSON.stringify(lock, null, 2) + '\n'],
];
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backups = [];
try {
  for (const [file] of updates) {
    const backup = `${file}.backup-excel-viewer-${stamp}`;
    fs.copyFileSync(file, backup); backups.push([file, backup]);
  }
  for (const [file, contents] of updates) atomicWrite(file, contents);
} catch (error) {
  for (const [file, backup] of backups.reverse()) {
    try { fs.copyFileSync(backup, file); } catch { /* retain backup even if rollback fails */ }
  }
  stop(`Patch failed; backups were retained. Details: ${error.message}`);
}
console.log('SUCCESS: Excel viewer patch applied without replacing the full app.jsx.');
console.log('Changed: src/app.jsx, package.json, package-lock.json');
console.log('Backups:', backups.map(([, backup]) => path.relative(ROOT, backup)).join(', '));
console.log('Next: npm run build');
